# Simple in-memory service registry
import threading

class ServiceRegistry:
    def __init__(self):
        self._services = {}
        self._lock = threading.Lock()

    def register(self, name, host, port):
        with self._lock:
            self._services.setdefault(name, [])
            entry = {'host': host, 'port': port}
            if entry not in self._services[name]:
                self._services[name].append(entry)
        print(f'Registered {name} at {host}:{port}')

    def discover(self, name):
        with self._lock:
            instances = self._services.get(name, [])
        return instances[0] if instances else None

    def deregister(self, name, host, port):
        with self._lock:
            entry = {'host': host, 'port': port}
            if name in self._services:
                self._services[name] = [i for i in self._services[name] if i != entry]
        print(f'Deregistered {name} at {host}:{port}')

registry = ServiceRegistry()
registry.register('user-service', 'host-a', 8001)
registry.register('user-service', 'host-b', 8001)
registry.register('order-service', 'host-c', 8002)

found = registry.discover('user-service')
print(f'Resolved user-service -> {found}')
registry.deregister('user-service', 'host-a', 8001)
